      "**第四部**轉向心理學，解釋雜訊的核心原因：個性與認知方式等個體差異、權衡各面向時的個人獨特性，以及使用相同量表卻運用方式各異；也探討我們為何對雜訊視而不見。**第五部**談實務：以[[決策保健|decision hygiene]]為題介紹減少雜訊的技巧，以醫療診斷、績效評估、法醫鑑定、雇用決定與一般預測五個案例說明，最後提出[[中介評估法|mediating assessments protocol, MAP]]。只關心實務的讀者可跳過第三、四部。",
      "**第六部**問：雜訊的適當水準是多少？反直覺的答案是**不是零**——有些雜訊無法消除、有些消除代價太大、有些會損害士氣等競爭價值，演算法也會引發各種反對。但作者無法接受目前的雜訊水準，敦促公私組織進行雜訊審查。每章最後都以引文列出可直接拿來用的簡短主張。"
