      "近年人工智慧，特別是[[機器學習|machine learning]]，讓機器能做許多向來只有人類能做的事：辨識臉孔、翻譯語言、判讀醫學影像，並以驚人的速度與正確性同時替數千位駕駛規畫路線；也能執行困難的預測任務——預測美國最高法院的判決、判斷哪些被告可能棄保潛逃、評估打到兒童服務中心的通報電話中哪一通最緊急、須最快派社工訪視。",
