      "本書承自橫跨半世紀的[[捷思法與偏誤研究計畫|heuristics and biases program]]；《快思慢想》(*Thinking, Fast and Slow*)回顧了它前40年的成果，探究「直覺思考的神妙與缺陷」。核心觀念是：被問到困難問題時，人會改用簡化的思考方式——捷思法。它們通常迅速實用，但有時導致**系統性、可預測**的判斷錯誤，也就是偏誤。",
      "這個計畫聚焦人類的**共通點**而非差異，所以熟悉[[心理偏誤|psychological bias]]的人常以為它必然產生[[統計偏誤|statistical bias]]（大部分測量或判斷以同方向偏離事實）。作者澄清：只有**普遍共有**的心理偏誤才產生統計偏誤；當判斷者的偏誤**情況或程度不同**，心理偏誤就產生**系統雜訊**。無論哪一種，都一定是錯誤。"
