      "**步驟1：憑直覺猜測。** 直覺並非毫無價值：快速的系統一思考能輕易把你手中的資訊放到預測量表上，配對出一個 GPA。這個猜測值就是「手中資訊具完全預測力」時的預測值，**請把它寫下來**（茱莉：3.8）。**步驟2：尋找平均值。** 退一步，暫時忘記你對茱莉的了解：如果你對她**一無所知**，最佳猜測就是她畢業時班級的平均 GPA，大約3.2。這是[[外部觀點|outside view]]的應用：把案例視為某類別的一員，並以統計角度思考那個類別，就像第4章的甘巴迪問題中，外部觀點引導我們詢問新任執行長成功留任的[[基本率|base rate]]。",
      "**步驟3：估計手中資訊的[[診斷價值|diagnostic value]]。** 這是最難的一步，要問：「我掌握的資訊有多少預測價值？」若只知道茱莉穿幾號鞋，就完全不給權重、維持平均值；若有她各科成績單，就有完全預測力（GPA 就是這些成績的平均）。兩極之間有許多灰色地帶：中學成績優異的診斷價值高於閱讀年齡、低於大學成績。任務是把它量化為**資訊與預測結果的相關係數**，除少數罕見情況外只能粗估。參考第12章：社會科學中相關係數高於0.5已非常罕見，許多有意義的相關約在0.2左右；茱莉的例子，**0.2大概是上限**。",
